verus! {

    /// Given a sequence `s` of length `n`, returns the sequence of all
    /// non‐empty prefixes of `s`, in order of increasing length.
    /// For each `0 <= i < n`, the `i`‐th element of the result has length `i+1`
    /// and matches `s[0..i]`.
    fn all_prefixes(s: Vec<char>) -> (result: Vec<Vec<char>>)
        ensures result.len() == s.len()
        ensures forall |i: usize|
            i < result.len() ==>
                result[i].len() == i + 1
        ensures forall |i: usize, j: usize|
            i < result.len() && j < result[i].len() ==>
                result[i][j] == s[j]
    {
        let mut result: Vec<Vec<char>> = Vec::new();
        let mut current: Vec<char> = Vec::new();
        let n = s.len();
        let mut i: usize = 0;
        while i < n
            invariant i <= n
            invariant result.len() == i
            invariant current.len() == i
            invariant forall |k: usize|
                k < result.len() ==>
                    result[k].len() == k + 1
            invariant forall |k: usize, j: usize|
                k < result.len() && j < result[k].len() ==>
                    result[k][j] == s[j]
            invariant forall |j: usize|
                j < current.len() ==>
                    current[j] == s[j]
            decreases n - i
        {
            // Extend the current prefix by one character,
            // then push a clone of it into the result.
            current.push(s[i]);
            result.push(current.clone());
            i += 1;
        }
        result
    }

    // Optional tests
    #[test]
    fn test_all_prefixes() {
        assert(all_prefixes(vec![]) == Vec::<Vec<char>>::new());
        let v = vec!['a','b','c','d'];
        let p = all_prefixes(v.clone());
        assert(p.len() == v.len());
        assert(p[0] == vec!['a']);
        assert(p[1] == vec!['a','b']);
        assert(p[2] == vec!['a','b','c']);
        assert(p[3] == vec!['a','b','c','d']);
    }
}